function o(n,{withTime:r=!1}={}){if(!n)return"—";const t=new Date(n);if(Number.isNaN(t.getTime()))return"—";const e=t.toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"});if(!r)return e;const i=t.toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"});return`${e}, ${i}`}function u(n){if(!n)return"—";const r=Date.now()-new Date(n).getTime(),t=Math.floor(r/6e4);if(t<1)return"just now";if(t<60)return`${t}m ago`;const e=Math.floor(t/60);if(e<24)return`${e}h ago`;const i=Math.floor(e/24);return i<30?`${i}d ago`:o(n)}function f(n,r){if(n==null)return"—";const t=Number(n);return Number.isFinite(t)?`${t.toLocaleString("en-IN")} ${r||"sq ft"}`:"—"}function a(n,r=90){return n?n.length>r?`${n.slice(0,r-1)}…`:n:""}function c(n){return!n&&n!==0?"—":n<1024?`${n} B`:n<1024*1024?`${(n/1024).toFixed(1)} KB`:`${(n/(1024*1024)).toFixed(2)} MB`}function s(n){const r={};return Object.entries(n||{}).forEach(([t,e])=>{e!=null&&e!==""&&(r[t]=e)}),r}export{a,s as b,o as c,c as d,f,u as t};
